odefun = @(x, y) [y(2); -y(1)];
bcfun = @(ya, yb) [ya(1); yb(1) - 1];
solinit = bvpinit(linspace(0, 1, 5), [0; 1]);
sol = bvp4c(odefun, bcfun, solinit);
y = deval(sol, 0.5);
fprintf('%.4f %.4f\n', y(1), sin(0.5)/sin(1))

odefun = @(x, y) [y(2); -y(1)];
bcfun = @(ya, yb) [ya(1); yb(1) - 1];
solinit = bvpinit(linspace(0, 1, 5), [0; 1]);
sol = bvp5c(odefun, bcfun, solinit);
y = deval(sol, 0.5);
fprintf('%.4f\n', y(1))

odefun = @(x, y) [y(2); -y(1)];
bcfun = @(ya, yb) [ya(1); yb(1) - 1];
sol = bvp4c(odefun, bcfun, bvpinit(linspace(0, 1, 5), [0; 1]));
solext = bvpxtend(sol, 2, [1; 0]);
solext.x(end)

opts = ddeset('RelTol', 1e-6, 'AbsTol', 1e-9);
sol = dde23(@(t, y, Z) -Z, 1, 1, [0 2], opts);
fprintf('%.5f\n', sol.y(end))

f = @(x, y) x.*y;
integral2(f, 0, 1, 0, 1)
integral2(f, 0, 1, 0, @(x) x)

f = @(t, y, yp) yp + y;
[t, y] = ode15i(f, [0 1], 1, -1);
fprintf('%.3f %.3f\n', y(end), exp(-1))
